    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Target and vector width for scheduling.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_i    = 64;  // tuneable tile size in the slow (row) dimension

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // -------------------------------------------------------------------------
    // Optimized single-timestep pipeline
    //
    // Instead of using RDom-based update definitions, we express each field at
    // time t+1 as a *pure* Func of the inputs at time t. This:
    //   - makes the dataflow explicit
    //   - allows straightforward parallelization and vectorization
    //   - avoids reduction scheduling complications
    //
    // We carefully reproduce the original C semantics, including boundary
    // behavior, and use explicit boundary conditions (clamp) wherever indices
    // might go out of bounds so that Halide's bounds inference is satisfied.
    // -------------------------------------------------------------------------

    // Clamp access to hz so that any speculative accesses generated by
    // vectorization near the boundaries stay in-bounds.
    Func hz_clamped("hz_clamped");
    {
        Expr jc = clamp(j, 0, ny - 1);
        Expr ic = clamp(i, 0, nx - 1);
        hz_clamped(j, i) = hz_param(jc, ic);
    }

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1");
    Func ex1_bc("ex1_bc"), ey1_bc("ey1_bc");
    Func hz1("hz1");

    // ey update:
    //
    // C code:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide layout is (j,i), so i is row, j is column.
    // We fold both loops into a single pure definition, using a select on i.
    ey1(j, i) = select(i == 0,
                       // First row: ey[0][j] = _fict_[t]
                       fict_param,
                       // Other rows: finite-difference update in the i-direction
                       ey_param(j, i) -
                           half * (hz_clamped(j, i) - hz_clamped(j, i - 1)));

    // ex update:
    //
    // C code:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // In Halide (j,i): j is the direction with the one-sided stencil.
    ex1(j, i) = select(j == 0,
                       // First column unchanged
                       ex_param(j, i),
                       // Other columns: finite-difference update in the j-direction
                       ex_param(j, i) -
                           half * (hz_clamped(j, i) - hz_clamped(j - 1, i)));

    // For hz we need ex1 and ey1 at (j+1,i) and (j,i+1). To avoid any possible
    // out-of-bounds reads (e.g. when j == ny-1 or i == nx-1 in vectorized code),
    // we create clamped versions of ex1 and ey1 that repeat edge values.
    ex1_bc(j, i) = ex1(clamp(j, 0, ny - 1),
                       clamp(i, 0, nx - 1));
    ey1_bc(j, i) = ey1(clamp(j, 0, ny - 1),
                       clamp(i, 0, nx - 1));

    // hz update:
    //
    // C code:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // In Halide (j,i), the interior region is j in [0, ny-2], i in [0, nx-2].
    // Outside that region, hz is unchanged.
    Expr interior = (i < nx - 1) && (j < ny - 1);

    hz1(j, i) = select(
        interior,
        hz_param(j, i) -
            seven_tenths *
                ((ex1_bc(j + 1, i) - ex1_bc(j, i)) +
                 (ey1_bc(j, i + 1) - ey1_bc(j, i))),
        // Boundary cells are not updated in the original C code
        hz_param(j, i));

    // -------------------------------------------------------------------------
    // Scheduling
    //
    // We compute each field at the root level, parallelize across rows (i),
    // and vectorize across columns (j), which are contiguous in memory.
    // We tile the i-dimension to improve cache locality on large grids.
    // The helper Funcs hz_clamped / ex1_bc / ey1_bc are left inlined.
    // -------------------------------------------------------------------------
    Var io("io"), ii("ii");

    ey1.compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    ex1.compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    hz1.compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ex_final(j, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ey_final(j, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << hz_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
