    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // Simple, cache-friendly schedule for initialization.
    Target target = get_host_target();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    init_fict.compute_root().vectorize(t, std::min(vec_width, tmax));
    init_ex.compute_root().parallel(i).vectorize(j, vec_width);
    init_ey.compute_root().parallel(i).vectorize(j, vec_width);
    init_hz.compute_root().parallel(i).vectorize(j, vec_width);

