    // -------------------------------------------------------------------------
    // Pure (non-update) definitions for the three field updates.
    //
    // We carefully encode the original loop-carried update order:
    //   1) ey: first row set from fict[t], remaining rows from hz differences
    //   2) ex: left column unchanged, remaining columns from hz differences
    //   3) hz: interior updated using *new* ex,ey; last row/column unchanged
    //
    // To keep everything pure and vectorizable, we use `clamp()` inside
    // index expressions instead of RDom-based updates; this avoids any
    // out-of-bounds accesses while preserving exact boundary semantics.
    // -------------------------------------------------------------------------

    // Dimension extents as Exprs (ny in dim 0, nx in dim 1).
    Expr ny_expr = ex_param.dim(0).extent();
    Expr nx_expr = ex_param.dim(1).extent();

    // --- ey update ----------------------------------------------------------
    //
    // Original C:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
