#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // ------------------------------------------------------------------
    // Scheduling for initialization
    // ------------------------------------------------------------------
    // We use a reasonably portable vector-width and parallelize across
    // the slow i-dimension (rows). All three 2D initializations share
    // the same schedule.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_i    = 32;  // tunable row-tile size

    Var io("io"), ii("ii");

    init_ex
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    init_ey
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    init_hz
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    // 1D fict array: just vectorize.
    init_fict
        .compute_root()
        .vectorize(t, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // Extents (runtime-sized) for interior checks and clamping
    Expr ny_extent = ex_param.dim(0).extent();  // number of columns (j)
    Expr nx_extent = ex_param.dim(1).extent();  // number of rows    (i)

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // ------------------------------------------------------------------
    // Pure (non-RDom) definitions for one full time-step.
    //
    // These are mathematically equivalent to the original loops:
    //
    //   // set top boundary of ey
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   // update ey for i >= 1
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    //   // update ex for j >= 1
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    //   // update interior of hz
    //   for (i = 0; i < nx-1; i++)
    //     for (j = 0; j < ny-1; j++)
    //       hz[i][j] -= 0.7 * (ex[i][j+1]-ex[i][j] + ey[i+1][j]-ey[i][j]);
    //
    //   // boundary cells of hz (i == nx-1 or j == ny-1) unchanged
    //
    // We encode the same logic as pointwise expressions with select()
    // and clamped indices to keep all accesses in-bounds.
    // ------------------------------------------------------------------

    // ey_new:
    //   i == 0: ey_new[0][j] = fict_param
    //   i >  0: ey_old[i][j] - 0.5 * (hz_old[i][j] - hz_old[i-1][j])
    //
    // Note: max(i-1, 0) makes the expression well-defined for i == 0,
    // but that branch is never used in the final select for i == 0.
    ey1(j, i) = select(
        i == 0,
        fict_param,
        ey_param(j, i) -
            half * (hz_param(j, i) - hz_param(j, max(i - 1, 0)))
    );

    // ex_new:
    //   j == 0: ex_new[i][0] = ex_old[i][0]
    //   j >  0: ex_old[i][j] - 0.5 * (hz_old[i][j] - hz_old[i][j-1])
    //
    // Again, max(j-1, 0) keeps indices in-bounds for j == 0, but that
    // branch is not used when j == 0.
    ex1(j, i) = select(
        j == 0,
        ex_param(j, i),
        ex_param(j, i) -
            half * (hz_param(j, i) - hz_param(max(j - 1, 0), i))
    );

    // hz_new:
    //   interior (i < nx-1 && j < ny-1):
    //       hz_old[i][j] - 0.7 * (ex_new[i][j+1]-ex_new[i][j]
    //                             + ey_new[i+1][j]-ey_new[i][j])
    //   boundary (i == nx-1 || j == ny-1):
    //       hz_old[i][j] (unchanged)
    //
    // We clamp the neighbor indices so that the expression is defined
    // everywhere; for boundary points the select() chooses the
    // "unchanged" branch, so the clamped values are never used
    // semantically.
    Expr interior = (i < nx_extent - 1) && (j < ny_extent - 1);

    Expr ex_right = ex1(min(j + 1, ny_extent - 1), i);
    Expr ey_down  = ey1(j, min(i + 1, nx_extent - 1));

    hz1(j, i) = select(
        interior,
        hz_param(j, i) -
            seven_tenths *
                ((ex_right - ex1(j, i)) +
                 (ey_down  - ey1(j, i))),
        // Boundary cells: no update.
        hz_param(j, i)
    );

    // ------------------------------------------------------------------
    // Scheduling for the FDTD step
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_i    = 32;  // tunable row-tile size

    Var io("io"), ii("ii");

    // ex1 and ey1 are simple 2D stencils from the old fields.
    // We parallelize over rows (i) in tiles and vectorize across columns (j).
    ex1
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    ey1
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    // hz1 depends on ex1 and ey1, so we compute it after them, with
    // the same schedule pattern for good cache behavior.
    hz1
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(j, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ex_final(j, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ey_final(j, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << hz_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
